(file: string, r: string = ''): boolean => {
    const root = r || parse(file).root || '.'
    let ret: boolean
    if (file === root) ret = false
    else {
      const m = map.get(file)
      ret = m !== undefined ? m : mapHas(dirname(file), root)
    }

    map.set(file, ret)
    return ret
  }

patched_function:
(file: string, r: string = '', depth = 0): boolean => {
    /* c8 ignore start - excessive caution */
    if (depth >= MAX) {
      map.set(file, false)
      return false
    }
    /* c8 ignore stop */
    const root = r || parse(file).root || '.'
    let ret: boolean
    if (file === root) ret = false
    else {
      const m = map.get(file)
      ret = m !== undefined ? m : mapHas(dirname(file), root, depth + 1)
    }

    map.set(file, ret)
    return ret
  }

